/* Public ordinary-user child: same numeric limits and inherited seccomp policy. */
#define _GNU_SOURCE
#include <errno.h>
#include <grp.h>
#include <linux/audit.h>
#include <linux/filter.h>
#include <linux/seccomp.h>
#include <signal.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/prctl.h>
#include <sys/resource.h>
#include <sys/syscall.h>
#include <unistd.h>

#define DENY(n) BPF_JUMP(BPF_JMP|BPF_JEQ|BPF_K,(n),0,1), BPF_STMT(BPF_RET|BPF_K,SECCOMP_RET_ERRNO|EPERM)
int main(int argc, char **argv) {
    if (argc < 2 || getuid() == 0 || geteuid() == 0) {
        fputs("ordinary nonroot execution required\n", stderr);
        return 126;
    }
    struct rlimit mem={2UL*1024*1024*1024,2UL*1024*1024*1024}, cpu={120,121};
    struct rlimit file={16UL*1024*1024,16UL*1024*1024}, fds={64,64}, proc={64,64}, core={0,0};
    if (setrlimit(RLIMIT_AS,&mem)||setrlimit(RLIMIT_CPU,&cpu)||setrlimit(RLIMIT_FSIZE,&file)||
        setrlimit(RLIMIT_NOFILE,&fds)||setrlimit(RLIMIT_NPROC,&proc)||setrlimit(RLIMIT_CORE,&core)) {perror("rlimit");return 3;}
    sigset_t empty;
    sigemptyset(&empty);
    if (sigprocmask(SIG_SETMASK, &empty, NULL)) {perror("signal mask");return 3;}
    struct sock_filter filter[]={
        BPF_STMT(BPF_LD|BPF_W|BPF_ABS,offsetof(struct seccomp_data,arch)),
        BPF_JUMP(BPF_JMP|BPF_JEQ|BPF_K,AUDIT_ARCH_X86_64,1,0),
        BPF_STMT(BPF_RET|BPF_K,SECCOMP_RET_KILL_PROCESS),
        BPF_STMT(BPF_LD|BPF_W|BPF_ABS,offsetof(struct seccomp_data,nr)),
        BPF_JUMP(BPF_JMP|BPF_JGE|BPF_K,0x40000000,0,1),
        BPF_STMT(BPF_RET|BPF_K,SECCOMP_RET_KILL_PROCESS),
        DENY(__NR_socket),DENY(__NR_socketpair),DENY(__NR_connect),
        DENY(__NR_shmget),DENY(__NR_shmat),DENY(__NR_shmctl),
        DENY(__NR_semget),DENY(__NR_semop),DENY(__NR_semctl),DENY(__NR_semtimedop),
        DENY(__NR_msgget),DENY(__NR_msgsnd),DENY(__NR_msgrcv),DENY(__NR_msgctl),
        DENY(__NR_kill),DENY(__NR_tkill),DENY(__NR_tgkill),DENY(__NR_ptrace),
        DENY(__NR_process_vm_readv),DENY(__NR_process_vm_writev),DENY(__NR_unshare),DENY(__NR_setns),
        DENY(__NR_mount),DENY(__NR_umount2),DENY(__NR_pivot_root),DENY(__NR_chroot),DENY(__NR_setsid),DENY(__NR_setpgid),
        DENY(__NR_setuid),DENY(__NR_setgid),DENY(__NR_setreuid),DENY(__NR_setregid),DENY(__NR_setresuid),DENY(__NR_setresgid),DENY(__NR_setgroups),
        DENY(__NR_open_by_handle_at),DENY(__NR_name_to_handle_at),DENY(__NR_bpf),DENY(__NR_keyctl),DENY(__NR_add_key),DENY(__NR_request_key),
        DENY(__NR_perf_event_open),DENY(__NR_userfaultfd),DENY(__NR_io_uring_setup),DENY(__NR_io_uring_enter),DENY(__NR_io_uring_register),
        DENY(424), /* x86_64 pidfd_send_signal */
        DENY(438), /* x86_64 pidfd_getfd */
        BPF_JUMP(BPF_JMP|BPF_JEQ|BPF_K,435,0,1), BPF_STMT(BPF_RET|BPF_K,SECCOMP_RET_ERRNO|ENOSYS),
        BPF_JUMP(BPF_JMP|BPF_JEQ|BPF_K,__NR_clone,0,4),
        BPF_STMT(BPF_LD|BPF_W|BPF_ABS,offsetof(struct seccomp_data,args[0])),
        BPF_JUMP(BPF_JMP|BPF_JSET|BPF_K,0x7e820000,0,1),
        BPF_STMT(BPF_RET|BPF_K,SECCOMP_RET_ERRNO|EPERM),
        BPF_STMT(BPF_LD|BPF_W|BPF_ABS,offsetof(struct seccomp_data,nr)),
        BPF_STMT(BPF_RET|BPF_K,SECCOMP_RET_ALLOW)
    };
    struct sock_fprog p={.len=sizeof(filter)/sizeof(filter[0]),.filter=filter};
    if (prctl(PR_SET_DUMPABLE,0,0,0,0)||prctl(PR_SET_NO_NEW_PRIVS,1,0,0,0)||prctl(PR_SET_SECCOMP,SECCOMP_MODE_FILTER,&p)) {perror("seccomp");return 5;}
    {
        struct sock_filter no_fork[]={
            BPF_STMT(BPF_LD|BPF_W|BPF_ABS,offsetof(struct seccomp_data,nr)),
            DENY(__NR_fork),DENY(__NR_vfork),DENY(__NR_clone),
            BPF_STMT(BPF_RET|BPF_K,SECCOMP_RET_ALLOW)
        };
        struct sock_fprog q={.len=sizeof(no_fork)/sizeof(no_fork[0]),.filter=no_fork};
        if (prctl(PR_SET_SECCOMP,SECCOMP_MODE_FILTER,&q)) {perror("seccomp nofork");return 5;}
    }
    execvp(argv[1], argv + 1);
    perror("execvp");
    return 127;
}
